SELECT COUNT(DISTINCT CASE WHEN af > 0.01 THEN allele_id END) AS copy_number_variants_above_1_percent
FROM genotypes
JOIN variants ON genotypes.variant_id = variants.id;

SELECT MAX(end_pos - pos) AS longest_insertion_length
FROM variants
WHERE variant_type = 'INS';

SELECT MAX(end_pos - pos) AS max_insertion_length, pos AS genomic_position
FROM variants
WHERE variant_type = 'INDEL' AND chrom = '22' AND alt > ref;

SELECT DISTINCT v.chrom, v.pos, v.ref, v.alt
FROM variants v
JOIN clinvar c ON v.chrom = c.chrom AND v.pos = c.pos AND v.ref = c.ref AND v.alt = c.alt;

SELECT AVG(end_pos - pos) AS average_span
FROM variants
WHERE chrom = '22' AND variant_type = 'duplication';
